def readable(x):
 if isinstance(x,list): return [readable(v) for v in x]
 if isinstance(x,dict): return {k:readable(v) for k,v in x.items()}
 if not isinstance(x,str) or x.startswith('https://'): return x
 x=re.sub(r'([,;:])(?=\S)',r'\1 ',x)
 x=re.sub(r'(?<=[A-Za-z0-9])\(', ' (',x)
 x=re.sub(r'\)(?=[A-Za-z0-9])',') ',x)
 x=re.sub(r'([a-z])(\d)',r'\1 \2',x)
 x=re.sub(r'(\d)([a-z])',r'\1 \2',x)
 x=re.sub(r'\b(HR|RR|SE|CI|Day|Days|Two|Table)(?=\d)',r'\1 ',x)
 x=re.sub(r'(?<=\d)%(?=[A-Za-z])','% ',x)
 for a,b in {'NCCPmonotherapy':'NCCP monotherapy','Child-PughA':'Child-Pugh A','B50%':'B 50%','Cnot':'C not','CurrentEMA':'Current EMA','CrCl≥':'CrCl ≥','EBCTCG2011':'EBCTCG 2011','ATLAS2013':'ATLAS 2013','CONFIRM2014':'CONFIRM 2014','FALCON2016':'FALCON 2016','FALCON2025':'FALCON 2025','EMAFaslodex':'EMA Faslodex','IrishRowexSmPC':'Irish Rowex SmPC'}.items(): x=x.replace(a,b)
 return x
def save(name,data): (H/name).write_text(json.dumps(readable(data),ensure_ascii=False,indent=2)+'\n')

