T['monitoring_schedule']['rows'][1]={'label':'Heart-rhythm checks','cells':['ECG and electrolytes if heart-rhythm risk indicates','Repeat according to risk, symptoms and product','Prompt review for palpitations, fainting or dizziness','No routine echo timetable for tamoxifen alone','Follow any identified abnormality']}
