def ep(endpoint,metric,result,interpretation,status,source,**kw):return {'endpoint':endpoint,'metric':metric,'result_text':result,'interpretation':interpretation,'analysis_status':status,'sources':[source],**kw}
tstud=[{'trial':'EBCTCG2011','population':'20 randomized early-breast trials;21,457 women overall;ER-positive efficacy analysis10,645.','comparison':'About5years adjuvant tamoxifen versus no tamoxifen.','outcomes':[{'endpoint':'Breast-cancer recurrence','measure':'Rate ratio','values':'Years0–4:0.53(SE0.03);years5–9:0.68(SE0.06);both2p<0.00001. Years10–14:0.97(SE0.10).','interpretation':'Earlier recurrence gains persist after treatment ends; the later near-unity rate ratio is not loss of the prior benefit.'},{'endpoint':'Breast-cancer mortality','measure':'Rate ratio','values':'Years0–4:0.71;years5–9:0.66;years10–14:0.68.','interpretation':'Roughly one-third lower breast-cancer mortality through15years; do not label this as overall survival.'}],'limitations':['Absolute benefit depends on baseline recurrence risk. Relative effects are not absolute risk reductions.','ER-negative disease showed little or no effect. This historical adjuvant comparison does not quantify metastatic benefit or rank modern endocrine combinations.'],'sources':[EB]},
{'trial':'ATLAS2013','population':'12,894 randomized after5years of tamoxifen;breast-cancer efficacy among6,846 ER-positive women;harms among all receptor groups.','comparison':'Continue to10years versus stop at5years.','outcomes':[{'endpoint':'Cumulative recurrence risk','timepoint':'Years5–14','intervention':21.4,'comparator':25.1,'unit':'%'},{'endpoint':'Breast-cancer mortality','timepoint':'Years5–14','intervention':12.2,'comparator':15.0,'unit':'%'},{'endpoint':'All-cause mortality','values':'639/3428 versus722/3418 deaths;P=.01.','interpretation':'Overall mortality was reduced in the ER-positive efficacy analysis; these event counts are not a fixed-time survival percentage.'}],'harms':'Pulmonary embolus RR1.87(95%CI1.13–3.07);endometrial cancer years5–14:3.1%versus1.6%.','limitations':['Benefit became more apparent after year10. Longer treatment is an individual risk–benefit decision.','Do not conflate efficacy population with all-receptor safety analysis or convert cause-specific mortality into OS.'],'sources':[AT]},
{'trial':'aTTom2013','publication_type':'ASCO meeting abstract;not a full-text efficacy report at this source.','population':'6,953 women:2,755 ER-positive and4,198 ER-untested, after5years tamoxifen.','comparison':'Continue to10years versus stop at5years.','outcomes':[{'endpoint':'Recurrence','values':'580/3468 versus672/3485;P=.003.'},{'endpoint':'All-cause mortality','values':'849 versus910 deaths;P=.1.','interpretation':'Overall mortality comparison in this report was not statistically significant; do not present it as a proven OS advantage.'}],'limitations':['Includes a large ER-untested population.','Later period subgroup effects and combined ATLAS/aTTom analyses differ from the overall aTTom result. Do not silently substitute a pooled result.','Abstract endometrial-risk confidence interval appears internally inconsistent; no numerical CI reused here.'],'sources':[ATT]}]
fstud=[{'trial':'CONFIRM final OS2014','population':'736 postmenopausal women with ER-positive advanced breast cancer after endocrine therapy.','comparison':'Fulvestrant500mg versus250mg.','outcomes':[{'endpoint':'OS','intervention':26.4,'comparator':22.3,'unit':'months','hr':0.81,'ci':'0.69–0.96','p':'.02 (nominal)','maturity':'554deaths;75.3%'}],'limitations':['Final OS testing had no multiplicity adjustment.','Historical dose comparison does not establish superiority over modern combinations.','The250mg historical comparator does not override an individual hepatic-dose decision.'],'sources':[CO]},
{'trial':'FALCON2016 PFS','population':'462 postmenopausal endocrine-therapy-naive women with HR-positive/HER2-negative advanced breast cancer.','comparison':'Fulvestrant500mg versus anastrozole1mg.','outcomes':[{'endpoint':'PFS','intervention':16.6,'comparator':13.8,'unit':'months','hr':0.797,'ci':'0.637–0.999','p':'.0486'}],'limitations':['Endocrine-naive population differs from NCCP00361 prior adjuvant anti-oestrogen relapse/progression indications.','Monotherapy trial;does not compare with capivasertib or CDK4/6 combinations.'],'sources':[FP]},
{'trial':'FALCON2025 final OS','population':'Same462-patient randomized endocrine-naive population;314deaths(68.0%)at11July2022cutoff.','comparison':'Fulvestrant500mg versus anastrozole1mg.','outcomes':[{'endpoint':'OS','intervention':44.8,'comparator':42.7,'unit':'months','hr':0.97,'ci':'0.77–1.21','p':'.7579','interpretation':'No statistically significant OS difference.'}],'subgroup':'Nonvisceral subgroup n208:HR0.85(95%CI0.60–1.20);not statistically significant. Do not claim a proven subgroup survival advantage.','limitations':['Prespecified final OS;descriptive analyses with nominal P values.','Medians are not individual life-expectancy gains. PFS improvement does not establish OS improvement.'],'sources':[FO]}]
tpanel={'trial':'EBCTCG;ATLAS;supportive aTTom duration context','population':'ER-positive early breast cancer;initial adjuvant treatment and extension decisions are distinct.','comparison':'EBCTCG:about5years versus none. ATLAS/aTTom:continue to10years versus stop at5years.','applicability':'NCCP00253 also includes advanced disease;these adjuvant results do not provide a metastatic survival estimate.','endpoints':[ep('OS','ATLAS overall mortality in the ER-positive population','639/3428 versus722/3418 deaths;P=.01.','Overall mortality was lower with extended treatment in ATLAS;not a fixed-time survival percentage.','Published randomized follow-up',AT,definition='Death from any cause after randomization at completion of5years tamoxifen.',limitations='Different endpoint from breast-cancer mortality;use the correct denominator and population.')],'qualitative_result':'EBCTCG2011:ER-positive recurrence rate ratios0.53 during years0–4 and0.68 during years5–9;breast-cancer mortality fell by about one-third through15years. ATLAS years5–14 recurrence was21.4%versus25.1%and breast-cancer mortality12.2%versus15.0%. These are recurrence and cause-specific mortality results,not DFS or OS percentages.','limitations':['Absolute benefit depends on recurrence risk.','aTTom corroborates recurrence reduction but its overall mortality comparison was not significant(P=.1);it included many ER-untested patients and is sourced here to a meeting abstract.','Extension is not automatic for everyone;benefit and harm populations in ATLAS differ.'],'harms':'ATLAS:extended treatment increased pulmonary embolus risk(RR1.87)and endometrial cancer(years5–14:3.1%versus1.6%).','sources':[EB,AT,ATT],'checked':D}
fpanel={'trial':'CONFIRM dose comparison;FALCON endocrine-naive context','population':'CONFIRM:postmenopausal ER-positive advanced disease after endocrine therapy. FALCON:postmenopausal HR-positive/HER2-negative endocrine-naive advanced disease.','comparison':'CONFIRM:fulvestrant500mg versus250mg. FALCON:fulvestrant500mg versus anastrozole1mg.','applicability':'Keep the populations and comparators separate. NCCP00361 does not acquire endocrine-naive eligibility from FALCON;none of these trials evaluates capivasertib/fulvestrant.','endpoints':[ep('OS','CONFIRM median overall survival','', 'Numerically longer OS with500mg;P=.02 was nominal without multiplicity adjustment.','Final OS;75.3%maturity',CO,intervention_label='Fulvestrant500mg',comparator_label='Fulvestrant250mg',intervention_value=26.4,comparator_value=22.3,unit='months',hr='0.81',ci='0.69–0.96',limitations='Historical dose comparison;not proof against modern combinations and not a reason to reverse hepatic-dose adjustment.'),ep('PFS','FALCON median progression-free survival','', 'PFS improved in the endocrine-naive population(P=.0486).','Primary PFS analysis',FP,intervention_label='Fulvestrant500mg',comparator_label='Anastrozole1mg',intervention_value=16.6,comparator_value=13.8,unit='months',hr='0.797',ci='0.637–0.999',limitations='Population differs from the specific NCCP00361 indications.'),ep('OS','FALCON median overall survival','', 'No statistically significant OS difference(P=.7579).','Prespecified final OS;68.0%maturity;descriptive nominal testing',FO,intervention_label='Fulvestrant500mg',comparator_label='Anastrozole1mg',intervention_value=44.8,comparator_value=42.7,unit='months',hr='0.97',ci='0.77–1.21',followup='Data cutoff11July2022',limitations='Nonvisceral subgroup HR0.85(95%CI0.60–1.20)was also not significant;do not claim proven subgroup OS benefit.')],'limitations':['Median differences do not estimate one individual’s additional lifespan.','PFS and OS are distinct outcomes.','These monotherapy studies do not quantify modern capivasertib/CDK4/6 combination benefit.'],'harms':'Consider injection-site reactions and neuropathy,bleeding risk with IM administration,hepatic effects,asthenia,flushes and joint/muscle symptoms.','sources':[CO,FP,FO],'checked':D}
trat={'summary':'Tamoxifen blocks ER-driven growth in breast tissue and is an endocrine option across pre- and postmenopausal ER-positive NCCP00253 settings. Active-metabolite formation and tissue-specific effects explain interaction checks and individualized clot,uterine and bone review.','setting':'Adjuvant or advanced ER-positive breast cancer within NCCP00253.','line':'Adjuvant initial or extended endocrine plan;advanced therapy according to the consultant plan.','factors':['Confirm ER positivity and exact setting.','Review menopause,prior endocrine treatment,recurrence risk and tolerability.','Review VTE history,uterine symptoms,eye disease,liver function and interacting medicines.','Treatment duration and switching are planned decisions,not automatic continuation.'],'alternatives':['An aromatase inhibitor may be an alternative in an appropriate postmenopausal or ovarian-suppression plan;its bone and joint risks differ.','Choice of an advanced-disease endocrine combination depends on previous treatment,disease features and the separate regimen eligibility.'],'limitations':'Trial benefits are population-specific;do not rank regimens across unrelated studies or infer prevention indications.','sources':[src('NCCP00253v6',NCCP_T),src('IrishRowexSmPC',ROW),EB,AT]}
frat={'summary':'Fulvestrant antagonizes and degrades the oestrogen receptor,providing a different endocrine mechanism from lowering oestrogen production. The initial loading schedule establishes exposure before28-day maintenance. The NCCP00361 card is monotherapy in a specified post-adjuvant anti-oestrogen setting.','setting':'Postmenopausal ER-positive locally advanced/metastatic breast cancer.','line':'Relapse or progression on or after adjuvant anti-oestrogen therapy as specified by NCCP00361.','factors':['Confirm prior endocrine exposure,menopausal state and exact indication.','Assess pace and symptoms of disease,performance status and suitability for endocrine treatment.','Reconcile hepatic impairment/current dose and IM bleeding/nerve risk.','Assess whether a separate molecularly selected or CDK4/6 combination plan is intended.'],'alternatives':['A separate fulvestrant combination may be appropriate when its own indication and safety criteria are met;capivasertib/fulvestrant uses00947.','Other endocrine agents or non-endocrine systemic treatment depend on previous therapy,disease urgency and patient priorities.'],'limitations':'EMA broader indications and FALCON endocrine-naive data do not silently broaden this NCCPmonotherapy card. Critical visceral disease requires specialist decision-making,not a rule that every visceral metastasis excludes endocrine therapy.','sources':[src('NCCP00361v4',NCCP_F),src('EMAFaslodex',EMA),CO,FP,FO]}
save('evidence.json',{'release':'0.84.20','checked':D,'audience':'clinician_only','profiles':{'00253':{'treatment_rationale':trat,'evidence_at_a_glance':tpanel,'studies':tstud},'00361':{'treatment_rationale':frat,'evidence_at_a_glance':fpanel,'studies':fstud}},'renderer_note':'Tamoxifen recurrence and breast-cancer-mortality are preserved as exact study outcomes and labelled narrative. They must not be relabelled DFS/OS merely to fit renderer endpoint keys.'})
